import React, { useState } from 'react';
import { 
  CheckCircle2, 
  Circle, 
  Clock, 
  TrendingUp, 
  Target, 
  ArrowRight,
  AlertCircle,
  HelpCircle,
  MinusCircle
} from 'lucide-react';
import { DayData, Task, Category } from '../types';
import { motion, AnimatePresence } from 'framer-motion';

interface DashboardProps {
  dayData: DayData;
  toggleTask: (day: number, taskId: string) => void;
  skipTask: (day: number, taskId: string) => void;
  currentDay: number;
}

const Dashboard: React.FC<DashboardProps> = ({ 
  dayData, 
  toggleTask, 
  skipTask, 
  currentDay 
}) => {
  const [pointHistory, setPointHistory] = useState<{id: string, points: number}[]>([]);

  const handleToggle = (taskId: string, points: number, isCompleted: boolean) => {
    toggleTask(currentDay, taskId);
    if (!isCompleted) {
      const id = Math.random().toString(36).substr(2, 9);
      setPointHistory(prev => [...prev, { id, points }]);
      setTimeout(() => {
        setPointHistory(prev => prev.filter(p => p.id !== id));
      }, 1000);
    }
  };

  const categories: Category[] = [
    'Morning Routine', 
    'English Learning', 
    'Trading', 
    'Coding/DSA', 
    'Flutter/React', 
    'Night Review'
  ];

  const phaseInfo = {
    1: { title: "Phase 1: Foundation", desc: "Flutter Focus", range: "Day 1-30", color: "from-blue-600 to-cyan-400" },
    2: { title: "Phase 2: Fullstack", desc: "Flutter + React Intro", range: "Day 31-60", color: "from-indigo-600 to-purple-400" },
    3: { title: "Phase 3: Mastery", desc: "Full Stack + Trading", range: "Day 61-180", color: "from-purple-600 to-pink-400" }
  };

  const getPhase = (day: number) => {
    if (day <= 30) return phaseInfo[1];
    if (day <= 60) return phaseInfo[2];
    return phaseInfo[3];
  };

  const phase = getPhase(currentDay);
  const completedTasks = dayData.tasks.filter(t => t.completed).length;
  const totalTasks = dayData.tasks.length;
  const progressPercent = Math.round((completedTasks / totalTasks) * 100);

  return (
    <div className="p-8 max-w-7xl mx-auto space-y-10">
      {/* Floating Point Popups */}
      <div className="fixed top-20 right-10 z-[100] pointer-events-none">
        <AnimatePresence>
          {pointHistory.map((p) => (
            <motion.div
              key={p.id}
              initial={{ opacity: 0, scale: 0.5, y: 20 }}
              animate={{ opacity: 1, scale: 1.2, y: -40 }}
              exit={{ opacity: 0, scale: 1.5, y: -80 }}
              className="text-2xl font-black text-emerald-400 drop-shadow-[0_0_10px_rgba(16,185,129,0.5)] mb-2"
            >
              +{p.points} PTS
            </motion.div>
          ))}
        </AnimatePresence>
      </div>

      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
        <div className="space-y-2">
          <motion.h2 
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            className="text-[10px] font-black tracking-[0.4em] text-blue-500 uppercase"
          >
            Mission Dashboard
          </motion.h2>
          <div className="flex items-center gap-4">
            <h1 className="text-5xl font-black tracking-tight text-white">Day {currentDay}</h1>
            <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest bg-gradient-to-r ${phase.color} text-white shadow-xl rotate-1`}>
              {phase.range}
            </div>
          </div>
          <p className="text-slate-400 font-bold uppercase tracking-widest text-xs flex items-center gap-2">
            <Calendar className="w-3 h-3" /> {new Date(dayData.date).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}
          </p>
        </div>

        <div className="glass-card p-6 bg-gradient-to-br from-white/10 to-transparent flex items-center gap-8 border-white/5 hover:border-blue-500/30 transition-colors group">
          <div className="relative w-24 h-24">
            <svg className="progress-ring w-24 h-24">
              <circle className="text-white/5" stroke="currentColor" strokeWidth="6" fill="transparent" r="40" cx="48" cy="48" />
              <motion.circle 
                initial={{ strokeDashoffset: 2 * Math.PI * 40 }}
                animate={{ strokeDashoffset: 2 * Math.PI * 40 * (1 - progressPercent / 100) }}
                className="text-blue-500 drop-shadow-[0_0_15px_rgba(59,130,246,0.6)]" 
                stroke="currentColor" strokeWidth="6" 
                strokeDasharray={`${2 * Math.PI * 40}`} 
                strokeLinecap="round" fill="transparent" r="40" cx="48" cy="48" 
              />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center">
              <span className="text-lg font-black text-white">{progressPercent}%</span>
            </div>
          </div>
          <div className="space-y-1">
            <p className="text-[10px] uppercase tracking-[0.2em] text-slate-500 font-black">Success Rate</p>
            <p className="text-3xl font-black flex items-baseline gap-2">
              {completedTasks} <span className="text-sm text-slate-500 font-bold tracking-widest uppercase">/ {totalTasks} DONE</span>
            </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-10">
        <div className="lg:col-span-2 space-y-12">
          {categories.map((cat, idx) => {
            const catTasks = dayData.tasks.filter(t => t.category === cat);
            if (catTasks.length === 0) return null;
            return (
              <motion.section 
                key={cat} 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: idx * 0.1 }}
                className="space-y-6"
              >
                <div className="flex items-center justify-between px-2">
                  <h3 className="text-xl font-black flex items-center gap-3 text-slate-100 italic uppercase tracking-tighter">
                    <div className="w-2 h-2 bg-blue-500 rounded-full shadow-[0_0_12px_rgba(59,130,246,1)]" />
                    {cat}
                  </h3>
                  <div className="flex items-center gap-4">
                    <span className="text-[10px] uppercase tracking-widest font-black text-slate-500">
                      {catTasks.filter(t => t.completed).length}/{catTasks.length} COMPLETED
                    </span>
                  </div>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                  {catTasks.map((task) => (
                    <motion.div 
                      key={task.id} 
                      whileHover={{ scale: 1.03, y: -5 }}
                      whileTap={{ scale: 0.98 }}
                      className={`glass-card p-5 group cursor-pointer transition-all border-white/5 relative overflow-hidden ${
                        task.completed ? 'bg-blue-600/10 border-blue-500/20 shadow-[0_10px_30px_rgba(59,130,246,0.1)]' : 'hover:border-white/20'
                      }`}
                      onClick={() => handleToggle(task.id, task.points, task.completed)}
                    >
                      {task.completed && (
                        <motion.div 
                          initial={{ scale: 0, opacity: 0 }}
                          animate={{ scale: 1, opacity: 0.1 }}
                          className="absolute -right-4 -bottom-4"
                        >
                          <CheckCircle2 size={100} className="text-blue-500 font-bold" />
                        </motion.div>
                      )}

                      <div className="flex items-start justify-between gap-5 relative z-10">
                        <div className="space-y-2 flex-1">
                          <p className={`font-black text-md leading-tight tracking-tight ${task.completed ? 'text-blue-400' : 'text-slate-100 group-hover:text-white transition-colors'}`}>
                            {task.title}
                          </p>
                          <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-slate-500">
                            <Clock size={12} className="text-blue-500/50" /> {task.time}
                          </div>
                        </div>
                        <div className={`w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${
                          task.completed 
                            ? 'bg-blue-500 border-blue-500 text-white shadow-[0_0_15px_rgba(59,130,246,0.5)]' 
                            : 'border-slate-700 bg-slate-800 text-transparent group-hover:border-slate-500'
                        }`}>
                          <CheckCircle2 size={18} />
                        </div>
                      </div>

                      <div className="flex items-center justify-between mt-6 relative z-10">
                        <div className={`text-[10px] font-black px-3 py-1 rounded-full uppercase tracking-tighter ${
                          task.completed ? 'bg-blue-500 text-white' : 'bg-white/5 text-slate-500 border border-white/5'
                        }`}>
                          +{task.points} PTS
                        </div>
                        {!task.completed && (
                          <button 
                            onClick={(e) => { e.stopPropagation(); skipTask(currentDay, task.id); }}
                            className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full border transition-all ${
                              task.skipped 
                                ? 'bg-orange-600 border-orange-500 text-white' 
                                : 'text-slate-600 border-slate-800 hover:border-slate-600 hover:text-slate-400'
                            }`}
                          >
                            {task.skipped ? 'SKIPPED' : 'SKIP'}
                          </button>
                        )}
                      </div>
                    </motion.div>
                  ))}
                </div>
              </motion.section>
            );
          })}
        </div>

        <div className="space-y-10">
           <div className="glass-card p-8 bg-gradient-to-br from-indigo-600/10 via-transparent to-transparent border-white/5 overflow-hidden relative">
             <div className="absolute top-0 right-0 p-4 opacity-5 pointer-events-none">
                <Clock size={150} className="text-white rotate-12" />
             </div>
             <h3 className="text-lg font-black mb-8 flex items-center justify-between uppercase tracking-widest italic">
                Daily Timeline
                <AnimatedPulseDot />
             </h3>
             <div className="space-y-8 relative ml-4 border-l-2 border-white/5 pb-2">
                {[
                  { time: '06:00', task: 'Wake & Flow', desc: 'MORNING' },
                  { time: '07:00', task: 'English', desc: 'LEARNING' },
                  { time: '09:00', task: 'Trading', desc: 'LIVE' },
                  { time: '19:00', task: 'Analysis', desc: 'TRADING' },
                  { time: '21:00', task: 'DSA & Dev', desc: 'CODING' },
                  { time: '23:30', task: 'Reflection', desc: 'REVIEW' }
                ].map((item, i) => (
                  <div key={i} className="relative pl-8 group">
                    <div className="absolute -left-[9px] top-1.5 w-4 h-4 rounded-full border-4 border-[#020617] bg-slate-700 group-hover:bg-blue-500 group-hover:shadow-[0_0_15px_rgba(59,130,246,1)] transition-all" />
                    <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest group-hover:text-blue-500 transition-colors">{item.time} {item.desc}</p>
                    <p className="text-md font-black text-slate-200 uppercase tracking-tighter">{item.task}</p>
                  </div>
                ))}
             </div>
           </div>

           <motion.div 
             whileHover={{ scale: 1.02 }}
             className="glass-card p-8 bg-orange-600/5 border-orange-500/20 shadow-2xl relative overflow-hidden group"
           >
              <div className="absolute -right-10 -top-10 w-32 h-32 bg-orange-500/10 blur-3xl group-hover:bg-orange-500/20 transition-all" />
              <div className="flex items-center gap-4 mb-6 relative z-10">
                <div className="w-14 h-14 rounded-3xl bg-orange-600/20 flex items-center justify-center text-orange-500 shadow-xl border border-orange-500/10 ring-4 ring-orange-500/5">
                  <AlertCircle size={28} />
                </div>
                <div>
                  <h4 className="font-black text-white uppercase text-xs tracking-widest">Discipline Protocal</h4>
                  <p className="text-[10px] text-orange-400 uppercase font-black tracking-widest">Active Enforcement</p>
                </div>
              </div>
              <p className="text-sm font-medium text-slate-300 leading-relaxed relative z-10 italic">
                "Skipping <span className="text-orange-400 font-black">Development</span> or <span className="text-orange-400 font-black">Trading</span> costs <span className="text-orange-400 font-black">-10 PTS</span>. The system tracks every move."
              </p>
           </motion.div>
        </div>
      </div>
    </div>
  );
};

const AnimatedPulseDot = () => (
  <div className="flex items-center gap-2">
    <span className="text-[10px] font-black text-emerald-400 uppercase tracking-widest">Live Schedule</span>
    <span className="relative flex h-3 w-3">
      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
      <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500 shadow-[0_0_8px_#10b981]"></span>
    </span>
  </div>
);

const Calendar = ({ className }: { className?: string }) => (
  <svg className={className} width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"></rect><line x1="16" y1="2" x2="16" y2="6"></line><line x1="8" y1="2" x2="8" y2="6"></line><line x1="3" y1="10" x2="21" y2="10"></line></svg>
);

export default Dashboard;
